	@Test
	@SetSystemProperty(key = "rdf4j.lmdb.nativeQueryEngine.enabled", value = "true")
	@SetSystemProperty(key = "rdf4j.lmdb.islands.enabled", value = "false")
	@SetSystemProperty(key = "rdf4j.lmdb.rootPipeline.enabled", value = "false")
	@SetSystemProperty(key = "rdf4j.lmdb.parallel.threads", value = "2")
	@SetSystemProperty(key = "rdf4j.lmdb.parallel.maxTasks", value = "2")
	@SetSystemProperty(key = "rdf4j.lmdb.parallel.rangePartition.enabled", value = "false")
	void hostedDistinctDeduplicatesAcrossNativeJoinInputOrder() {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setDirectAdjacencyEnabled(false)
				.setDirectAdjacencyMode(DirectAdjacencyMode.DISABLED);
		config.setExperimentalQueryOptimizations(true);
		LmdbStore store = new LmdbStore(new File(dir, "native_residual_parallel"), config);
		LmdbNativeEvaluationStrategyFactory factory = new LmdbNativeEvaluationStrategyFactory(null);
		// Keep this algebra order fixed so the native operator can choose its own physical scan order independently.
		factory.setOptimizerPipeline(List::of);
		store.setEvaluationStrategyFactory(factory);
		SailRepository repository = new SailRepository(store);
		repository.init();
		try (var connection = repository.getConnection()) {
			ValueFactory vf = connection.getValueFactory();
			IRI p = vf.createIRI("urn:p");
			IRI q = vf.createIRI("urn:q");
			IRI gate = vf.createIRI("urn:gate");
			IRI s1 = vf.createIRI("urn:s1");
			IRI s2 = vf.createIRI("urn:s2");
			IRI x1 = vf.createIRI("urn:x1");
			IRI x2 = vf.createIRI("urn:x2");
			IRI x3 = vf.createIRI("urn:x3");
			connection.begin();
			// One native morsel visits these three probe keys in index order.
			connection.add(x1, q, gate);
			connection.add(x2, q, gate);
			connection.add(x3, q, gate);
			connection.add(s1, p, x1);
			connection.add(s2, p, x2);
			connection.add(s1, p, x3);
			connection.commit();

			StatementPattern first = new StatementPattern(new Var("s"), TupleExprs.createConstVar(p), new Var("x"));
			StatementPattern second = new StatementPattern(new Var("x"), TupleExprs.createConstVar(q),
					TupleExprs.createConstVar(gate));
			first.setResultSizeEstimate(3);
			second.setResultSizeEstimate(3);
			BindingSetAssignment optionalRows = new BindingSetAssignment();
			optionalRows.setBindingSets(List.of(new ListBindingSet(List.of("r"), gate)));
			// INTERSECT keeps the OPTIONAL and DISTINCT generic, while the left BGP can use native operators.
			LeftJoin mixed = new LeftJoin(new Join(first, second),
					new Intersection(optionalRows, optionalRows.clone()));
			Projection projected = new Projection(mixed, new ProjectionElemList(new ProjectionElem("s"),
					new ProjectionElem("r")));
			ParsedTupleQuery parsed = new ParsedTupleQuery(new QueryRoot(new Distinct(projected)));
			SailTupleQuery query = new SailTupleQuery(parsed, connection);
			query.setForcedLmdbExecutionStrategy("parallelPipelines,nestedLoop");

			assertThat(QueryResults.asList(query.evaluate())).containsExactlyInAnyOrder(
					new ListBindingSet(List.of("s", "r"), s1, gate),
					new ListBindingSet(List.of("s", "r"), s2, gate));
			assertThat(query.explain(Explanation.Level.Executed).toString())
					.contains("nativeExecutionPath=parallelPipelines");
		} finally {
			repository.shutDown();
		}
	}

