	@Test
	void pendingTransactionChangesDisablePartitionedDistinct() {
		Repository lmdb = lmdb("pending", false);
		try (RepositoryConnection conn = lmdb.getConnection(); var partitioned = new LmdbPartitionedDistinctProbe()) {
			ValueFactory vf = conn.getValueFactory();
			conn.begin();
			conn.add(vf.createIRI("urn:a0"), vf.createIRI("urn:p"), vf.createIRI("urn:fresh"));
			conn.add(vf.createIRI("urn:fresh"), vf.createIRI("urn:q"), vf.createIRI("urn:cfresh"));
			TupleQuery tupleQuery = conn.prepareTupleQuery(QueryLanguage.SPARQL, PLAIN_DISTINCT);
			String explain = tupleQuery.explain(Explanation.Level.Executed).toString();
			int rows = 0;
			try (var result = tupleQuery.evaluate()) {
				while (result.hasNext()) {
					result.next();
					rows++;
				}
			}
			conn.rollback();
			// 14882 committed distinct rows plus the (urn:a0, urn:cfresh) row only visible in the transaction
			assertThat(rows).isEqualTo(14883);
			assertThat(explain).doesNotContain("statementOrder");
			assertThat(partitioned.opened()).isZero();
		} finally {
			lmdb.shutDown();
		}
	}

	private void load(Repository repo) {
		Random rnd = new Random(42);
		int nA = 3000;
		int nB = 40;
		int nC = 7;
		List<String[]> triples = new ArrayList<>();
		for (int a = 0; a < nA; a++) {
			for (int k = 0; k < 4; k++) {
				triples.add(new String[] { "a" + a, "p", "b" + rnd.nextInt(nB) });
			}
		}
		for (int b = 0; b < nB; b++) {
			triples.add(new String[] { "b" + b, "q", "c" + rnd.nextInt(nC) });
			triples.add(new String[] { "b" + b, "q", "c" + rnd.nextInt(nC) });
		}
		Collections.shuffle(triples, rnd);
		try (RepositoryConnection conn = repo.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			conn.begin();
			for (String[] t : triples) {
				IRI s = vf.createIRI("urn:" + t[0]);
				IRI p = vf.createIRI("urn:" + t[1]);
				IRI o = vf.createIRI("urn:" + t[2]);
				conn.add(s, p, o);
			}
			conn.commit();
		}
	}

	private Repository lmdb(String sub, boolean nativeEnabled) {
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(nativeEnabled);
		config.setExperimentalQueryOptimizations(true);
		return lmdb(sub, config);
	}

	private Repository lmdb(String sub, LmdbStoreConfig config) {
		LmdbStore store = new LmdbStore(new File(dir, sub), config);
		SailRepository repo = new SailRepository(store);
		repo.init();
		load(repo);
		return repo;
	}

	private Repository memory() {
		SailRepository repo = new SailRepository(new MemoryStore());
		repo.init();
		load(repo);
		return repo;
	}

	private static Map<String, Integer> run(Repository repo, String query, StringBuilder explainOut) {
		try (RepositoryConnection conn = repo.getConnection()) {
			Map<String, Integer> counts = new LinkedHashMap<>();
			TupleQuery tupleQuery = conn.prepareTupleQuery(QueryLanguage.SPARQL, query);
			if (explainOut != null) {
				explainOut.append(tupleQuery.explain(Explanation.Level.Executed));
			}
			try (var result = tupleQuery.evaluate()) {
				while (result.hasNext()) {
					BindingSet bindingSet = result.next();
					List<String> parts = new ArrayList<>();
					for (String name : new TreeSet<>(bindingSet.getBindingNames())) {
						parts.add(name + "=" + bindingSet.getValue(name));
					}
					counts.merge(parts.toString(), 1, Integer::sum);
				}
			}
			return counts;
		}
	}
